Rules.InvariantScript:
If(
    IsEmpty(BeachCombo.SelectedItems),
    Notify("Please select a beach", NotificationType.Error),
    Patch(
        LifeguardDetails,
        LookUp(LifeguardDetails, ID = varVolunteer.ID),
        {
            'Selected Beaches': Concat(BeachCombo.SelectedItems, 'Beach Names', ", ")
        }
    );
    Set(varVolunteer, LookUp(LifeguardDetails, ID = varVolunteer.ID));
    Notify("Beach selection saved!", NotificationType.Success)
)

If(
    IsBlank(UploadedImage1.Image),
    Notify("Please upload your certificate", NotificationType.Error),
    Patch(
        LifeguardDetails,
        LookUp(LifeguardDetails, ID = varVolunteer.ID),
        {
            Certificate: UploadedImage1.Image
        }
    );
    Set(varVolunteer, LookUp(LifeguardDetails, ID = varVolunteer.ID));
    Notify("Certificate uploaded successfully!", NotificationType.Success);
    Navigate('Volunteer-Page 2')
)
